    { ime: "Euronews Travel: footwear checks and one-way trails in Cinque Terre", url: "https://www.euronews.com/travel/2025/04/11/hiking-in-cinque-terre-this-spring-be-prepared-for-footwear-checks-and-one-way-systems" },
    { ime: "Associazione Verace Pizza Napoletana: the recipe", url: "https://www.pizzanapoletana.org/en/ricetta_pizza_napoletana" },
    { ime: "Consorzio del Parmigiano Reggiano: seals and marks", url: "https://www.parmigianoreggiano.com/product-guide-seals-and-marks" },
    { ime: "Reid's Italy: Rialto market", url: "https://www.reidsitaly.com/destinations/veneto/venice/sights/rialto-market.html" },
    { ime: "Alto-Adige.com: getting to Lago di Braies", url: "https://www.alto-adige.com/informazioni-utili/raggiungere-il-lago-di-braies" }
